"use client";

import { AuthGuard } from "@/components/auth/AuthGuard";
import { useAppSelector } from "@/store/hooks";
import { useAppDispatch } from "@/store/hooks";
import { clearCredentials } from "@/store/features/auth/authSlice";
import { clearAuthSession } from "@/lib/auth-storage";
import { useAdminLogoutMutation } from "@/store/api/authApi";
import { useRouter } from "next/navigation";

export default function AdminDashboardPage() {
  return (
    <AuthGuard>
      <DashboardStub />
    </AuthGuard>
  );
}

function DashboardStub() {
  const router = useRouter();
  const dispatch = useAppDispatch();
  const admin = useAppSelector((s) => s.auth.admin);
  const [logout, { isLoading }] = useAdminLogoutMutation();

  async function onLogout() {
    try {
      await logout().unwrap();
    } catch {
      // clear local session even if API fails
    }
    dispatch(clearCredentials());
    clearAuthSession();
    router.replace("/login");
  }

  return (
    <div className="flex min-h-screen flex-col items-center justify-center gap-4 bg-[#0a0a0a] px-4 text-[#f5efe0]">
      <p className="font-[family-name:var(--font-cinzel)] text-2xl tracking-[0.12em] text-[#e8c547]">
        Admin Dashboard
      </p>
      <p className="text-sm text-[#c5bba3]">
        Signed in as{" "}
        <span className="font-semibold text-[#e8c547]">
          {admin?.displayName ?? admin?.username}
        </span>
        {admin?.role ? ` (${admin.role})` : null}
      </p>
      <p className="max-w-md text-center text-sm text-[#8a8070]">
        Login auth is working. Dashboard UI comes next.
      </p>
      <button
        type="button"
        onClick={onLogout}
        disabled={isLoading}
        className="sd-gold-btn mt-2 rounded-lg px-6 py-2.5 text-sm font-bold tracking-[0.14em] text-[#1a1204] disabled:opacity-60"
      >
        {isLoading ? "LOGGING OUT…" : "LOG OUT"}
      </button>
    </div>
  );
}
